#!/usr/bin/env python3
"""Single source for both C4 Markdown formats; generated by render.py."""
import sys
from html import escape
from textwrap import wrap
from canvas import Canvas

TITLE = 'Container — request path'
BOUNDARY = 'Platform host and central registry'
NODES = [('client',
  'Typed client SDK',
  'Library in caller process',
  'sdk/client.ts',
  'Named handlers, bearer, X-Trace-Id',
  False),
 ('server',
  'Server process',
  'Deno process',
  'platform/server.ts',
  'HTTP auth, SQLite document reads/writes, backup and ingest timers',
  True),
 ('reader',
  'Reader process',
  'Deno child process',
  'platform/reader.ts',
  'Event-log DuckDB; ingest and named analysis',
  True),
 ('files',
  'Application documents',
  'SQLite 3 WAL files',
  'DATA_DIR; TENANTS_DIR',
  'Legacy app.sqlite; TENANTS_DIR/tenantId.db; one file per tenant',
  True),
 ('pg',
  'Central registry',
  'Postgres 17 process/store',
  'docker-compose.yml; platform/tenants/',
  'Tenants, hashed keys, users, sessions, memberships',
  True),
 ('tenants',
  'Tenant/auth CLI',
  'Deno process',
  'scripts/tenants.ts; scripts/auth.ts',
  'Tenant administration and headless email/password',
  True),
 ('migration',
  'Migration runner',
  'Deno process',
  'scripts/db/migrate.ts',
  'Journaled, advisory-locked SQL migrations',
  True),
 ('objects',
  'Object storage',
  'External system / filesystem',
  'S3_BASE_URL or LOCAL_OBJECT_DIR',
  'apps/appId/ snapshots and manifests',
  False)]
EDGES = [('client', 'server', 'HTTP JSON + bearer + trace'),
 ('server', 'reader', 'JSONL IPC ping/ingest/analysis'),
 ('server', 'files', 'node:sqlite; read-only queries and serialized mutations'),
 ('server', 'pg', 'Postgres protocol; registry SQL and session auth'),
 ('tenants', 'pg', 'Postgres protocol; tenant/key or auth operations'),
 ('migration', 'pg', 'Postgres protocol; journal and migration SQL'),
 ('server', 'objects', 'Snapshot verification/hash; S3 HTTPS or local publication')]
NOTES = 'The writer and reader remain separate OS processes and native module graphs. The central Postgres\nconnection is acquired lazily for registry use; TENANCY=off preserves app tokens and legacy files.\nEach app has a LocalFolderRouter over the shared TENANTS_DIR/tenantId.db path.\nDifferent physical layouts need distinct tenants because the schema guard rejects switching layouts. Document queries use fresh read-only node:sqlite connections in the server, with authenticated tenant routing selecting the file. Application documents stay in SQLite.\nBetter Auth is mounted in the server at /api/auth/*; scripts/auth.ts is the headless CLI. The future\ncontrol-plane router is not implemented. E2E uses ephemeral Postgres, distinct tenants for layouts, and fresh Better Auth servers per layout.'
NAME = 'c4-container-platform'


def picture():
    cv = Canvas(width=72, height=260)
    row = 2
    for inside in (True, False):
        group = [n for n in NODES if n[5] == inside]
        if not inside:
            cv.frame(0, 0, row, 71, BOUNDARY)
            row += 2
        for offset in range(0, len(group), 2):
            bottoms = []
            for col, (_, title, kind, path, detail, _) in enumerate(group[offset:offset+2]):
                lines = [part for line in [title, '[' + kind + ']', path, detail]
                         for part in wrap(line, 28, break_on_hyphens=False)]
                bottoms.append(cv.box(row, 3 + col*35, 32, lines))
            row = max(bottoms) + 2
    return cv.render()


def mermaid():
    lines = ['flowchart TB', '    subgraph platform["' + BOUNDARY + '"]']
    for inside in (True, False):
        for id, title, kind, path, detail, within in NODES:
            if within == inside:
                label = '<br/>'.join(escape(s, quote=True) for s in [title, '['+kind+']', path, detail])
                lines.append('        ' + id + '["' + label + '"]')
        if inside:
            lines.append('    end')
    for i, (a, b, label) in enumerate(EDGES, 1):
        lines.append(f'    {a} -->|"({i}) {label}"| {b}')
    lines += ['    classDef planned stroke-dasharray: 5 3',
              '    classDef person fill:#fff,stroke-width:2px',
              '    classDef external fill:#f4f4f4']
    for id, _, kind, _, _, inside in NODES:
        if kind == 'Person':
            lines.append(f'    class {id} person')
        elif not inside:
            lines.append(f'    class {id} external')
    return '\n'.join(lines)


def document(github):
    text = '# ' + TITLE + '\n\nAudited against landed main `643b706` on 2026-10-11 (item 27); re-checked for FFI-01 and FFI-02 at `398be14`\non 2026-10-13. Both formats are generated from\n'
    text += '`diagrams/' + NAME + '.py`; numbered relationships are identical. All boxes describe landed code.\n\n'
    if github:
        text += '```mermaid\n' + mermaid() + '\n```\n'
    else:
        text += '<!-- c4-render: diagrams/' + NAME + '.py -->\n\n```text\n' + picture() + '\n```\n'
    names = {n[0]: n[1] for n in NODES}
    text += '\n## Relationships\n\n| # | From | To | Relationship |\n| - | --- | --- | --- |\n'
    for i, (a,b,label) in enumerate(EDGES,1):
        text += f'| {i} | {names[a]} | {names[b]} | {label} |\n'
    return text + '\n## Runtime notes\n\n' + NOTES + '\n'


if __name__ == '__main__':
    if '--github' in sys.argv:
        print(document(True), end='')
    elif '--terminal' in sys.argv:
        print(document(False), end='')
    else:
        print(picture())
